<?php
require_once __DIR__.'/includes/bootstrap.php';
require_role(['admin','accueil','caissier','production']);
$page_title='Tableau de bord';
$pdo=db();
$userRole=role();
$stats=['clients'=>(int)$pdo->query('SELECT COUNT(*) FROM clients WHERE supprime=0')->fetchColumn(),'orders'=>(int)$pdo->query("SELECT COUNT(*) FROM commandes WHERE statut<>'retire'")->fetchColumn(),'ready'=>(int)$pdo->query("SELECT COUNT(*) FROM commandes WHERE statut='pret'")->fetchColumn()];
$financialAccess=in_array($userRole,['admin','accueil','caissier'],true);
if($financialAccess){$stats['revenue']=(float)$pdo->query('SELECT COALESCE(SUM(montant),0) FROM paiements WHERE YEAR(date_paiement)=YEAR(CURRENT_DATE) AND MONTH(date_paiement)=MONTH(CURRENT_DATE)')->fetchColumn();}
if($userRole==='admin'){$stats['margin']=(float)$pdo->query('SELECT COALESCE(SUM(l.sous_total-l.quantite*l.cout_unitaire),0) FROM commande_lignes l JOIN commandes o ON o.id=l.commande_id WHERE YEAR(o.date_depot)=YEAR(CURRENT_DATE) AND MONTH(o.date_depot)=MONTH(CURRENT_DATE)')->fetchColumn();$stats['users']=(int)$pdo->query('SELECT COUNT(*) FROM utilisateurs WHERE actif=1')->fetchColumn();$stats['messages']=(int)$pdo->query('SELECT COUNT(*) FROM communications WHERE statut IN (\'prepare\',\'envoye\',\'envoye_manuellement\')')->fetchColumn();$stats['ratings']=(int)$pdo->query("SELECT COUNT(*) FROM avis_clients WHERE statut='nouveau'")->fetchColumn();$stats['requests']=(int)$pdo->query("SELECT COUNT(*) FROM demandes_clients WHERE statut='en_attente'")->fetchColumn();}
$recent=$pdo->query('SELECT o.id,o.reference AS code,o.date_promise AS date_prevue,o.total,o.statut,c.nom,c.prenom FROM commandes o JOIN clients c ON c.id=o.client_id ORDER BY o.id DESC LIMIT 8')->fetchAll();
if($userRole==='admin')$activity=$pdo->query('SELECT a.date_heure,a.action,a.table_cible,a.enregistrement_id,u.nom FROM journal_audit a LEFT JOIN utilisateurs u ON u.id=a.utilisateur_id ORDER BY a.id DESC LIMIT 10')->fetchAll();
require 'includes/header.php';
?>
<?php if($userRole==='admin'):?><div class="admin-page-heading"><div><p class="eyebrow">ESPACE DE PILOTAGE</p><h2>Bonjour <?=e($_SESSION['user']['name'])?></h2></div><a class="btn" href="order_new.php">＋ Nouveau dépôt</a></div><div class="admin-quick-links"><a href="users.php">⚙ Comptes · <?=$stats['users']?></a><a href="client_requests.php">⌖ Demandes · <?=$stats['requests']?></a><a href="ratings.php">★ Avis · <?=$stats['ratings']?> nouveaux</a><a href="messages.php">✉ Communications · <?=$stats['messages']?></a><a href="reports.php">▤ Rapports du mois</a><a href="settings.php">⚙ Paramètres</a></div><?php endif;?>
<div class="cards"><div class="stat"><span class="ico icon-clients">♙</span><div class="label">Clients enregistrés</div><strong><?=$stats['clients']?></strong><small>Base active</small></div><div class="stat"><span class="ico icon-orders">▤</span><div class="label">Commandes en cours</div><strong><?=$stats['orders']?></strong><small>À traiter ou retirer</small></div><div class="stat"><span class="ico icon-ready">✓</span><div class="label">Commandes prêtes</div><strong><?=$stats['ready']?></strong><small>En attente de retrait</small></div><?php if($financialAccess):?><div class="stat"><span class="ico icon-currency">₣</span><div class="label">Encaissements du mois</div><strong style="font-size:22px"><?=money($stats['revenue'])?></strong><small>Paiements enregistrés</small></div><?php endif;?><?php if($userRole==='admin'):?><div class="stat"><span class="ico">↗</span><div class="label">Marge brute estimée</div><strong style="font-size:22px"><?=money($stats['margin'])?></strong><small>Mois en cours</small></div><?php endif;?></div>
<div class="panel"><div class="panel-head"><h2>Dernières commandes</h2><?php if(can_manage()):?><a class="btn" href="order_new.php">＋ Nouveau dépôt</a><?php endif;?></div><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Client</th><th>Date prévue</th><th>Montant</th><th>État</th><th></th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><b><?=e($row['code'])?></b></td><td><?=e(trim(($row['prenom']??'').' '.$row['nom']))?></td><td><?=e($row['date_prevue'])?></td><td><?=money($row['total'])?></td><td><span class="badge <?=e($row['statut'])?>"><?=e(status_label($row['statut']))?></span></td><td><a class="btn light small" href="order_view.php?id=<?=(int)$row['id']?>">Ouvrir</a></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6" class="empty">Aucune commande pour le moment.</td></tr><?php endif;?></tbody></table></div></div>
<?php if($userRole==='admin'):?><div class="panel"><div class="panel-head"><h2>Activité récente</h2><a class="btn light small" href="reports.php">Voir les rapports</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Action</th><th>Module</th><th>Compte</th></tr></thead><tbody><?php foreach($activity as $event):?><tr><td><?=e($event['date_heure'])?></td><td><?=e($event['action'])?> · #<?=e($event['enregistrement_id']??'—')?></td><td><?=e($event['table_cible'])?></td><td><?=e($event['nom']??'Système')?></td></tr><?php endforeach;?><?php if(!$activity):?><tr><td colspan="4" class="empty">Les actions sensibles apparaîtront ici.</td></tr><?php endif;?></tbody></table></div></div><?php endif;?>
<?php require 'includes/footer.php';?>
